const t=k=>I[state.lang][k]||k;
const l=v=>typeof v==='string'?v:(v?.[state.lang]??v?.en??v?.ru??'');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v,c='EUR')=>new Intl.NumberFormat(state.lang==='ru'?'ru-RU':'en-GB',{style:'currency',currency:c,maximumFractionDigits:0}).format(Number(v)||0);
const date=d=>d?new Intl.DateTimeFormat(state.lang==='ru'?'ru-RU':'en-GB',{dateStyle:'medium'}).format(new Date(d)):'—';
const cookie=n=>decodeURIComponent(document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith(n+'='))?.split('=').slice(1).join('=')||'');
async function api(path,o={}){const m=(o.method||'GET').toUpperCase(),h={'content-type':'application/json',...(o.headers||{})};if(!['GET','HEAD'].includes(m)&&cookie('antiqua_csrf'))h['x-csrf-token']=cookie('antiqua_csrf');const r=await fetch(path,{...o,headers:h,credentials:'same-origin'});let d={};try{d=await r.json()}catch{}if(!r.ok){const e=new Error(d.error||'Request failed');e.status=r.status;e.data=d;throw e}return d}
function toast(text){const el=$('#toast');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
const statusPairs={ACTIVE:['Активно','Active'],LIVE:['Идут торги','Live'],CLOSED:['Завершено','Closed'],SCHEDULED:['Запланировано','Scheduled'],PENDING:['Ожидает ответа','Pending'],COUNTERED_BY_SELLER:['Встречное предложение продавца','Seller countered'],COUNTERED_BY_BUYER:['Встречное предложение покупателя','Buyer countered'],ACCEPTED:['Принято','Accepted'],DECLINED:['Отклонено','Declined'],AWAITING_PAYMENT_CONNECTOR:['Ожидает оплаты','Awaiting payment'],CANCELLED:['Отменено','Cancelled'],DRAFT:['Черновик','Draft'],CATALOGUE_REVIEW:['Каталожная проверка','Catalogue review'],CHANGES_REQUESTED:['Нужны изменения','Changes requested'],APPROVED:['Одобрено','Approved'],PUBLISHED:['Опубликовано','Published'],DISABLED:['Отключена','Disabled'],ENABLED:['Включена','Enabled'],PRIVATE:['Приватно','Private'],PUBLIC:['Публично','Public'],UNLISTED:['По ссылке','Unlisted'],PERSONAL:['Личная','Personal'],CURATED:['Кураторская','Curated'],DISTRIBUTED:['Распределённая','Distributed'],INSTITUTIONAL:['Институциональная','Institutional'],VERIFIED:['Подтверждено','Verified'],CANDIDATE:['Кандидат','Candidate'],KNOWN_PRIVATE:['Известно, приватно','Known private'],MISSING:['Не найдено','Missing'],UNKNOWN_LOCATION:['Местонахождение неизвестно','Unknown location'],USER_SUPPLIED:['Предоставлено владельцем','User supplied'],PLATFORM_RECORD:['Запись платформы','Platform record'],REVIEWED:['Проверено','Reviewed'],NO_FLAG:['Ограничений не отмечено','No flag'],REVIEW_REQUIRED:['Требуется проверка','Review required'],NOT_SCREENED:['Не проверено','Not screened'],NOT_STARTED:['Не начато','Not started'],NOT_CONFIGURED:['Не настроено','Not configured'],QUOTE_REQUIRED:['Нужен расчёт','Quote required'],QUOTE_READY:['Расчёт готов','Quote ready']};
function status(v){const p=statusPairs[String(v||'')];return p?(state.lang==='ru'?p[0]:p[1]):String(v||'—').replaceAll('_',' ')}
function relative(d){if(!d)return'';const mins=Math.max(0,Math.round((Date.now()-Date.parse(d))/60000));if(mins<2)return state.lang==='ru'?'только что':'just now';if(mins<60)return state.lang==='ru'?`${mins} мин назад`:`${mins}m ago`;const h=Math.round(mins/60);if(h<24)return state.lang==='ru'?`${h} ч назад`:`${h}h ago`;const days=Math.round(h/24);return state.lang==='ru'?`${days} дн назад`:`${days}d ago`}
function persistCompare(){localStorage.setItem('antiqua_compare',JSON.stringify(state.compare))}
function syncShell(){document.documentElement.lang=state.lang;document.title=`ANTIQUA — ${t('shop')}`;const labels={shop:t('shop'),auctions:t('auctions'),collections:t('collections'),exhibitions:t('exhibitions'),dealers:t('dealers'),account:t('account'),trust:t('trust')};$$('[data-nav]').forEach(a=>{const k=a.dataset.nav;if(labels[k])a.querySelector('span')?a.querySelector('span').textContent=labels[k]:a.textContent=labels[k]});$$('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===state.lang));const footer=$('#footerCopy');if(footer)footer.textContent=state.lang==='ru'?'Собирать · Исследовать · Объединять · Показывать · Приобретать · Сохранять':'Collect · Research · Reunite · Exhibit · Acquire · Preserve';const skip=$('.skip-link');if(skip)skip.textContent=state.lang==='ru'?'К содержанию':'Skip to content';const persona=$('#persona');if(persona)persona.textContent=state.me?.account?.roles?.includes('ADMIN')?(state.lang==='ru'?'Оператор':'Operator'):state.me?.account?.roles?.includes('SELLER')?t('sellerRole'):t('buyer');const trust=$('#trustNav');if(trust)trust.hidden=!state.me?.account?.roles?.some(r=>['CATALOGUER','TRUST_REVIEWER','ADMIN'].includes(r));syncNavigation()}
function syncNavigation(){const root=(location.hash.slice(1).split('/')[0]||'shop');$$('[data-nav]').forEach(a=>a.toggleAttribute('aria-current',a.dataset.nav===root))}
async function refresh(){const [catalog,health,collections,ensembles,exhibitions,me]=await Promise.all([api('/api/catalog'),api('/api/health'),api('/api/collections'),api('/api/ensembles'),api('/api/exhibitions'),api('/api/auth/me')]);state.catalog=catalog;state.health=health;state.collections=collections.collections||[];state.ensembles=ensembles.ensembles||[];state.exhibitions=exhibitions.exhibitions||[];state.me=me;if(!state.me.account&&health.preview){await api('/api/auth/demo-login',{method:'POST',body:JSON.stringify({persona:state.persona})});state.me=await api('/api/auth/me')}state.client=state.me.account?await api('/api/client-state'):null;syncShell()}
function sellerBy(id){return state.catalog.sellers.find(x=>x.id===id)}
function entryForLot(o){const li=state.catalog.listings.find(x=>x.lotId===o.id),au=state.catalog.auctions.find(x=>x.lotId===o.id);return{lot:o,listing:li||null,auction:au||null,seller:li?.seller||sellerBy(li?.sellerId),method:li?.saleType||(au&&au.state!=='CLOSED'?'AUCTION':'NOT_FOR_SALE'),price:li?.price??au?.currentBid??null,currency:li?.currency??au?.currency??o.currency??'EUR'}}
function discovery(){return state.catalog.lots.map(entryForLot).filter(x=>x.method!=='NOT_FOR_SALE')}
function filteredEntries(){let xs=discovery(),f=state.filters,q=f.q.trim().toLowerCase();if(q)xs=xs.filter(x=>[l(x.lot.title),l(x.lot.maker),l(x.lot.period),l(x.lot.department),l(x.lot.materials),l(x.lot.technique),l(x.lot.origin),x.seller?.name].join(' ').toLowerCase().includes(q));if(f.category!=='ALL')xs=xs.filter(x=>x.lot.department?.en===f.category);if(f.era!=='ALL')xs=xs.filter(x=>x.lot.period?.en===f.era);if(f.country!=='ALL')xs=xs.filter(x=>x.lot.origin?.en===f.country);if(f.material!=='ALL')xs=xs.filter(x=>String(x.lot.materials?.en||'').split(',').map(v=>v.trim()).includes(f.material));if(f.technique!=='ALL')xs=xs.filter(x=>x.lot.technique?.en===f.technique);if(f.condition!=='ALL')xs=xs.filter(x=>x.lot.conditionGrade===f.condition);if(f.location!=='ALL')xs=xs.filter(x=>x.lot.locationLabel?.en===f.location);if(f.purchaseMethod!=='ALL')xs=xs.filter(x=>x.lot.purchaseMethods?.includes(f.purchaseMethod));if(f.seller!=='ALL')xs=xs.filter(x=>x.listing?.sellerId===f.seller);if(f.priceMin!=='')xs=xs.filter(x=>Number(x.price)>=Number(f.priceMin));if(f.priceMax!=='')xs=xs.filter(x=>Number(x.price)<=Number(f.priceMax));if(f.sort==='PRICE_ASC')xs.sort((a,b)=>a.price-b.price);if(f.sort==='PRICE_DESC')xs.sort((a,b)=>b.price-a.price);if(f.sort==='ENDING')xs.sort((a,b)=>Date.parse(a.auction?.endsAt||'2999-01-01')-Date.parse(b.auction?.endsAt||'2999-01-01'));return xs}
function methodLabel(m){return m==='BUY_NOW'?t('buyNow'):m==='MAKE_OFFER'?t('makeOffer'):m==='AUCTION'?t('auction'):m==='PRIVATE_SALE'?t('privateSale'):t('notForSale')}
function isSaved(id){return state.client?.savedLots?.includes(id)}
function isCompared(id){return state.compare.includes(id)}
function card(entry){const o=entry.lot,s=entry.seller,auction=entry.auction,shop=entry.listing,commercial=auction?`${t('currentBid')}: ${money(auction.currentBid,auction.currency)}`:money(shop?.price,shop?.currency),action=entry.method==='AUCTION'?`<button class="primary-button" data-bid="${esc(auction.id)}" data-min="${auction.currentBid+auction.increment}">${t('bid')}</button>`:entry.method==='MAKE_OFFER'?`<button class="secondary-button" data-offer="${esc(shop.id)}" data-price="${shop.price}" data-currency="${shop.currency}">${t('offer')}</button>`:`<button class="secondary-button" data-buy="${esc(shop?.id||'')}">${t('buy')}</button>`;return`<article class="object-card v12-card" data-direct-card><div class="card-media-wrap"><button class="image-button" data-passport="${esc(o.id)}"><div class="object-image"><img loading="lazy" decoding="async" src="${esc(o.image)}" alt="${esc(l(o.title))}"></div></button><div class="card-chrome"><button class="round-action ${isSaved(o.id)?'active':''}" data-save="${esc(o.id)}" aria-label="${t('save')}">♡</button><button class="round-action ${isCompared(o.id)?'active':''}" data-compare="${esc(o.id)}" aria-label="${t('compare')}">⇄</button></div><span class="commerce-tag">${methodLabel(entry.method)}</span></div><div class="object-copy v12-card-copy"><div class="micro">${esc(l(o.department))} · ${esc(o.objectId)}</div><h3>${esc(l(o.title))}</h3><div class="muted">${esc(l(o.maker))} · ${esc(l(o.period))}</div><div class="passport-meta"><span>${esc(l(o.origin))}</span><span>${esc(l(o.materials))}</span></div><div class="object-price">${commercial}</div><div class="seller-mini">${s?`${esc(s.name)}${s.verified?' · ✓':''}`:auction?`${t('auction')} · ${esc(l(state.catalog.sale.title))}`:''}</div><div class="card-row v12-card-actions"><button class="quiet-button" data-passport="${esc(o.id)}">${t('passport')}</button>${state.me.account?.roles?.includes('BUYER')?action:''}</div></div></article>`}
function optionHtml(list,current,allLabel){return`<option value="ALL">${esc(allLabel)}</option>${(list||[]).map(x=>`<option value="${esc(x.value)}" ${x.value===current?'selected':''}>${esc(l(x.label))}</option>`).join('')}`}
function activeFilterCount(){return Object.entries(state.filters).filter(([k,v])=>!['q','sort'].includes(k)&&v!==''&&v!=='ALL').length}
function facetPanel(){const f=state.catalog.facets,F=state.filters;return`<aside class="facet-panel"><div class="facet-head"><strong>${t('filters')}</strong><button class="text-button" data-reset-filters>${t('reset')}</button></div><label>${t('category')}<select data-filter="category">${optionHtml(f.categories,F.category,t('all'))}</select></label><label>${t('era')}<select data-filter="era">${optionHtml(f.eras,F.era,t('all'))}</select></label><label>${t('country')}<select data-filter="country">${optionHtml(f.countries,F.country,t('all'))}</select></label><label>${t('material')}<select data-filter="material">${optionHtml(f.materials,F.material,t('all'))}</select></label><label>${t('technique')}<select data-filter="technique">${optionHtml(f.techniques,F.technique,t('all'))}</select></label><label>${t('condition')}<select data-filter="condition">${optionHtml(f.conditions,F.condition,t('all'))}</select></label><label>${t('location')}<select data-filter="location">${optionHtml(f.locations,F.location,t('all'))}</select></label><label>${t('purchase')}<select data-filter="purchaseMethod">${optionHtml(f.purchaseMethods,F.purchaseMethod,t('all'))}</select></label><label>${t('seller')}<select data-filter="seller">${optionHtml(f.sellers,F.seller,t('all'))}</select></label><div class="price-filter"><span>${t('price')}</span><div><input data-filter="priceMin" inputmode="numeric" type="number" min="0" placeholder="${f.price.min}" value="${esc(F.priceMin)}"><span>—</span><input data-filter="priceMax" inputmode="numeric" type="number" min="0" placeholder="${f.price.max}" value="${esc(F.priceMax)}"></div></div></aside>`}
function filterChips(){const f=state.filters,meta={category:t('category'),era:t('era'),country:t('country'),material:t('material'),technique:t('technique'),condition:t('condition'),location:t('location'),purchaseMethod:t('purchase'),seller:t('seller'),priceMin:'≥',priceMax:'≤'};return Object.entries(f).filter(([k,v])=>meta[k]&&v!==''&&v!=='ALL').map(([k,v])=>`<button class="filter-chip" data-clear-filter="${k}"><span>${meta[k]}</span>${esc(k.startsWith('price')?money(v):facetValueLabel(k,v))}<b>×</b></button>`).join('')}
function facetValueLabel(key,value){const map={category:'categories',era:'eras',country:'countries',material:'materials',technique:'techniques',condition:'conditions',location:'locations',purchaseMethod:'purchaseMethods',seller:'sellers'},item=state.catalog.facets[map[key]]?.find(x=>x.value===value);return item?l(item.label):value}
function shop(){const xs=filteredEntries();return`<section class="page section"><div class="section-head editorial-head"><div><div class="eyebrow">ANTIQUA · OBJECT NETWORK</div><h1>${t('shop')}</h1><p class="muted">${t('shopIntro')}</p></div><a class="secondary-button compare-head-button ${state.compare.length<2?'disabled':''}" href="#compare">${t('comparison')} · ${state.compare.length}</a></div><div class="catalog-search-row"><input id="catalogSearch" value="${esc(state.filters.q)}" placeholder="${t('search')}" autocomplete="off"><button class="secondary-button mobile-facet-trigger" data-open-filters>${t('filters')} ${activeFilterCount()?`· ${activeFilterCount()}`:''}</button><select data-filter="sort" class="sort-select"><option value="RECOMMENDED">${t('recommended')}</option><option value="PRICE_ASC" ${state.filters.sort==='PRICE_ASC'?'selected':''}>${t('priceAsc')}</option><option value="PRICE_DESC" ${state.filters.sort==='PRICE_DESC'?'selected':''}>${t('priceDesc')}</option><option value="ENDING" ${state.filters.sort==='ENDING'?'selected':''}>${t('ending')}</option></select></div><div class="active-filters" id="activeFilters">${filterChips()}</div><div class="catalog-layout">${facetPanel()}<div class="catalog-results"><div class="catalog-result-head"><span id="catalogCount">${xs.length} ${t('results')}</span></div><div class="object-grid" id="catalogGrid">${xs.length?xs.map(card).join(''):`<div class="empty-state catalog-empty">${t('noResults')}</div>`}</div></div></div></section>${compareDock()}`}
function auctionsView(){const entries=state.catalog.auctions.map(a=>entryForLot(state.catalog.lots.find(o=>o.id===a.lotId))).filter(x=>x.lot);return`<section class="page section"><div class="section-head"><div><div class="eyebrow">AUCTION INTEGRITY ENGINE</div><h1>${t('auctions')}</h1><p class="muted">${t('auctionIntro')}</p></div><div class="foundation-pill">${esc(state.health.auctionIntegrity.engine)}</div></div><div class="object-grid">${entries.map(card).join('')}</div></section>${compareDock()}`}
function collectionsView(){return`<section class="page section"><div class="section-head"><div><div class="eyebrow">${t('collectionGraph')}</div><h1>${t('collections')}</h1><p class="muted">${t('collectionIntro')}</p></div></div><div class="collection-grid">${state.collections.map(c=>{const cover=c.items?.find(x=>x.objectId===c.coverObjectId)?.object||c.items?.[0]?.object;return`<a class="collection-card" href="#collection/${esc(c.id)}"><div class="collection-cover">${cover?`<img loading="lazy" src="${esc(cover.image)}" alt="">`:''}</div><div class="collection-copy"><div class="micro">${status(c.collectionType)} · ${status(c.visibility)}</div><h2>${esc(l(c.title))}</h2><p>${esc(l(c.summary))}</p><strong>${c.items?.length||0} ${t('objects')}</strong></div></a>`}).join('')}</div><div class="section-head split-head"><div><div class="eyebrow">${t('virtualReunification')}</div><h2>${t('distributedEnsembles')}</h2></div></div><div class="ensemble-grid">${state.ensembles.map(e=>`<a class="ensemble-card" href="#ensemble/${esc(e.id)}"><div class="ensemble-orbit"><strong>${e.completeness?.knownPercent||0}%</strong><span>${t('known')}</span></div><div><div class="micro">${status(e.status)}</div><h2>${esc(l(e.title))}</h2><p>${esc(l(e.summary))}</p><div class="progress"><i style="width:${e.completeness?.verifiedPercent||0}%"></i></div><div class="ensemble-stats"><span>${t('verified')}: ${e.completeness?.verified||0}/${e.completeness?.total||0}</span><span>${t('missing')}: ${e.completeness?.missing||0}</span></div></div></a>`).join('')}</div></section>`}
function exhibitionsView(){return`<section class="page section"><div class="section-head"><div><div class="eyebrow">CURATED DIGITAL SPACE</div><h1>${t('exhibitions')}</h1><p class="muted">${t('exhibitionIntro')}</p></div></div><div class="exhibition-grid">${state.exhibitions.map(e=>{const cover=state.catalog.lots.find(x=>x.id===e.coverObjectId);return`<a href="#exhibition/${esc(e.id)}" class="exhibition-card"><div class="exhibition-image">${cover?`<img loading="lazy" src="${esc(cover.image)}" alt="">`:''}<span>${status(e.status)}</span></div><div class="exhibition-copy"><div class="micro">${t('onlineExhibition')}</div><h2>${esc(l(e.title))}</h2><p>${esc(l(e.subtitle))}</p><div class="text-link">${t('open')} →</div></div></a>`}).join('')}</div></section>`}
function dealersView(){return`<section class="page section"><div class="section-head"><div><div class="eyebrow">PROFESSIONAL TRADE</div><h1>${t('dealers')}</h1></div></div><div class="dealer-grid">${state.catalog.sellers.map(s=>`<a class="dealer-card dealer-link" href="#dealer/${esc(s.id)}"><div class="dealer-card-top"><div class="verified-line">${s.verified?'✓ '+t('verifiedDealer'):t('reviewPending')}</div><span class="dealer-place">${esc(l(s.city))}</span></div><h2>${esc(s.name)}</h2><p>${esc(l(s.about))}</p><div class="dealer-specialties">${(s.specialties||[]).slice(0,3).map(x=>`<span>${esc(l(x))}</span>`).join('')}</div><small>${s.since?`${t('since')} ${s.since}`:''}</small></a>`).join('')}</div></section>`}
async function dealerPage(id){const d=await api(`/api/sellers/${encodeURIComponent(id)}`),s=d.seller;return`<section class="dealer-profile"><div class="dealer-profile-hero"><div class="page"><a class="text-link" href="#dealers">← ${t('dealers')}</a><div class="dealer-profile-grid"><div><div class="eyebrow">${s.verified?'✓ '+t('verifiedDealer'):t('reviewPending')}</div><h1>${esc(s.name)}</h1><p class="lead">${esc(l(s.about))}</p><div class="dealer-meta"><span>${esc(l(s.city))}, ${esc(l(s.country))}</span>${s.since?`<span>${t('since')} ${s.since}</span>`:''}${s.responseHours?`<span>${t('response')} ${s.responseHours} ${t('hours')}</span>`:''}</div></div><aside class="dealer-trust-card"><strong>${s.verified?'✓':'…'}</strong><span>${s.verified?t('verifiedDealer'):t('reviewPending')}</span>${s.rating?`<b>${s.rating.toFixed(1)} / 5</b>`:''}</aside></div></div></div><div class="page section"><div class="block-head"><div><div class="eyebrow">${t('dealerStore')}</div><h2>${t('itemsAvailable')}</h2></div></div><div class="object-grid">${d.inventory.map(x=>card({lot:x.lot,listing:x,auction:null,seller:x.seller,method:x.saleType,price:x.price,currency:x.currency})).join('')}</div><div class="dealer-policy"><h2>${t('policies')}</h2><p>${esc(l(s.policies))}</p></div></div></section>${compareDock()}`}
function compareDock(){if(!state.compare.length)return'';return`<div class="compare-dock"><span>${t('comparison')}: <strong>${state.compare.length}/4</strong></span><div><button class="text-button" data-clear-compare>${t('clear')}</button><a class="primary-button" href="#compare">${t('compare')}</a></div></div>`}
function compareView(){const objects=state.compare.map(id=>state.catalog.lots.find(o=>o.id===id)).filter(Boolean);if(objects.length<2)return`<section class="page section"><div class="section-head"><div><div class="eyebrow">OBJECT STUDY</div><h1>${t('comparison')}</h1><p class="muted">${t('selectTwo')}</p></div></div></section>${compareDock()}`;const rows=[['maker',state.lang==='ru'?'Автор / мастерская':'Maker / workshop',o=>l(o.maker)],['period',t('era'),o=>l(o.period)],['origin',t('country'),o=>l(o.origin)],['materials',t('materials'),o=>l(o.materials)],['technique',t('techniqueLabel'),o=>l(o.technique)],['dimensions',t('dimensions'),o=>l(o.dimensions)],['condition',t('conditionGrade'),o=>l(o.conditionLabel)],['location',t('location'),o=>l(o.locationLabel)],['purchase',t('purchase'),o=>(o.purchaseMethods||[]).map(methodLabel).join(', ')],['price',t('price'),o=>{const e=entryForLot(o);return e.price!=null?money(e.price,e.currency):'—'}]];return`<section class="page section compare-page"><div class="section-head"><div><div class="eyebrow">OBJECT STUDY</div><h1>${t('comparison')}</h1><p class="muted">${t('compareIntro')}</p></div><button class="secondary-button" data-clear-compare>${t('clear')}</button></div><div class="compare-scroll"><div class="compare-grid" style="--compare-count:${objects.length}"><div class="compare-label"></div>${objects.map(o=>`<article class="compare-object"><button class="compare-remove" data-compare="${esc(o.id)}">×</button><button class="image-button" data-passport="${esc(o.id)}"><img src="${esc(o.image)}" alt=""></button><h2>${esc(l(o.title))}</h2><small>${esc(o.objectId)}</small></article>`).join('')}${rows.map(([,label,get])=>`<div class="compare-label">${esc(label)}</div>${objects.map(o=>`<div class="compare-cell">${esc(get(o))}</div>`).join('')}`).join('')}</div></div></section>${compareDock()}`}
function authView(){return`<section class="page section"><div class="auth-grid"><form id="login"><h2>${t('signIn')}</h2><label>Email<input name="email" type="email" autocomplete="email" required></label><label>${t('password')}<input name="password" type="password" autocomplete="current-password" required></label><button class="primary-button">${t('signIn')}</button></form><form id="register"><h2>${t('createAccount')}</h2><label>${t('name')}<input name="displayName" required></label><label>Email<input name="email" type="email" required></label><label>${t('password')}<input name="password" type="password" required></label><label>${t('accountType')}<select name="accountType"><option value="BUYER">${t('buyer')}</option><option value="SELLER">${t('sellerRole')}</option></select></label><button class="secondary-button">${t('createAccount')}</button></form></div></section>`}
const orderSteps=['ORDER_CREATED','AWAITING_PAYMENT_CONNECTOR','PAID','RELEASE_APPROVED','PACKING','SHIPPED','DELIVERED','OWNERSHIP_TRANSFERRED'];
function orderStepLabel(x){const m={ORDER_CREATED:t('orderCreated'),AWAITING_PAYMENT_CONNECTOR:t('awaitingPayment'),PAID:t('paid'),RELEASE_APPROVED:t('releaseApproved'),PACKING:t('packing'),SHIPPED:t('shipped'),DELIVERED:t('delivered'),OWNERSHIP_TRANSFERRED:t('ownershipTransferred')};return m[x]||status(x)}
function orderTimeline(o){let idx=orderSteps.indexOf(o.status);if(idx<0)idx=0;return`<div class="order-timeline">${orderSteps.map((s,i)=>`<div class="timeline-step ${i<=idx?'done':''}"><i></i><span>${orderStepLabel(s)}</span></div>`).join('')}</div>`}
function activityFeed(){const ns=state.client?.notifications||[];return`<aside class="activity-panel"><div class="block-head"><div><div class="eyebrow">${t('notifications')}</div><h2>${t('activity')}</h2></div>${ns.some(n=>!n.readAt)?`<button class="text-button" data-read-all>${t('readAll')}</button>`:''}</div><div class="activity-feed">${ns.length?ns.map(n=>`<article class="activity-item ${n.readAt?'':'unread'}"><i class="activity-mark"></i><div><strong>${esc(status(n.type))}</strong><p>${esc(Object.entries(n.payload||{}).slice(0,2).map(([k,v])=>`${k}: ${v}`).join(' · '))}</p></div><time>${relative(n.createdAt)}</time></article>`).join(''):`<div class="empty-state">${t('noActivity')}</div>`}</div></aside>`}
function accountView(){if(!state.me.account)return authView();const a=state.me.account,c=state.client,v=c.verification,isSeller=Boolean(c.seller),saved=(c.savedLots||[]).map(id=>state.catalog.lots.find(o=>o.id===id)).filter(Boolean);return`<section class="page section account-v12"><div class="account-hero"><div><div class="eyebrow">${isSeller?t('sellerRole'):t('buyer')}</div><h1>${esc(a.displayName)}</h1><p>${esc(a.email)}</p></div><div class="account-identity"><span>${esc(a.roles.map(status).join(' · '))}</span><b>${t('verification')}: ${status(v?.status||'NOT_STARTED')}</b></div></div><div class="v12-kpis"><div class="kpi"><strong>${saved.length}</strong><span>${t('saved')}</span></div><div class="kpi"><strong>${c.leadingLots?.length||0}</strong><span>${t('bids')}</span></div><div class="kpi"><strong>${c.offers?.length||0}</strong><span>${t('offers')}</span></div><div class="kpi"><strong>${c.orders?.length||0}</strong><span>${t('orders')}</span></div></div><div class="account-layout"><div>${isSeller?sellerWorkspace(c):buyerWorkspace(c,saved)}<section class="account-security"><div class="block-head"><div><div class="eyebrow">ACCOUNT PROTECTION</div><h2>${t('security')}</h2></div></div><div class="security-grid"><div><span>${t('roles')}</span><strong>${esc(a.roles.join(', '))}</strong></div><div><span>2FA</span><strong>${status(a.twofaStatus)}</strong></div><div><span>${esc(v?.caseType||'KYC')}</span><strong>${status(v?.status||'NOT_STARTED')}</strong></div><div><span>${t('persistence')}</span><strong>${esc(state.health.persistence.kind)}</strong></div></div>${a.twofaStatus==='DISABLED'?`<button class="secondary-button" data-setup-2fa>${t('setup2fa')}</button>`:''}</section></div>${activityFeed()}</div></section>`}
function buyerWorkspace(c,saved){return`<section class="account-block"><div class="block-head"><div><div class="eyebrow">COLLECTOR WORKSPACE</div><h2>${t('saved')}</h2></div></div>${saved.length?`<div class="account-card-grid compact">${saved.map(o=>`<article class="account-card"><button class="image-button mini-object" data-passport="${esc(o.id)}"><img src="${esc(o.image)}" alt=""></button><h3>${esc(l(o.title))}</h3><button class="quiet-button" data-passport="${esc(o.id)}">${t('open')}</button></article>`).join('')}</div>`:`<div class="empty-state">${t('noResults')}</div>`}</section><section class="account-block"><div class="block-head"><div><div class="eyebrow">NEGOTIATION</div><h2>${t('offers')}</h2></div></div>${c.offers?.length?`<div class="account-card-grid">${c.offers.map(o=>`<article class="account-card"><div class="account-card-head"><strong>${money(o.buyerAmount||o.sellerAmount,o.currency)}</strong><span class="status-pill">${status(o.status)}</span></div><h3>${esc(l(state.catalog.lots.find(x=>x.id===o.lotId)?.title)||o.lotId)}</h3></article>`).join('')}</div>`:`<div class="empty-state">${t('noOffers')}</div>`}</section><section class="account-block"><div class="block-head"><div><div class="eyebrow">POST-SALE</div><h2>${t('orders')}</h2></div></div>${c.orders?.length?`<div class="account-card-grid">${c.orders.map(orderCard).join('')}</div>`:`<div class="empty-state">${t('noOrders')}</div>`}</section>`}
function sellerWorkspace(c){const s=c.seller;return`<section class="account-block"><div class="block-head"><div><div class="eyebrow">DEALER WORKSPACE</div><h2>${t('inventory')}</h2></div></div><div class="account-card-grid compact">${s.listings.map(x=>`<article class="account-card"><div class="account-card-head"><span class="status-pill">${status(x.status)}</span><strong>${money(x.price,x.currency)}</strong></div><h3>${esc(l(x.lot.title))}</h3><small>${methodLabel(x.saleType)}</small></article>`).join('')}</div></section><section class="account-block"><div class="block-head"><div><div class="eyebrow">PUBLICATION PIPELINE</div><h2>${t('drafts')}</h2></div></div><div class="account-card-grid">${s.drafts.map(d=>`<article class="account-card draft-card"><div class="account-card-head"><span class="status-pill">${status(d.status)}</span><strong>${d.checklist.percent}%</strong></div><h3>${esc(l(d.title))}</h3><div class="progress"><i style="width:${d.checklist.percent}%"></i></div>${d.checklist.ready&&!['CATALOGUE_REVIEW','PUBLISHED'].includes(d.status)?`<button class="primary-button" data-submit-draft="${esc(d.id)}">${t('submitReview')}</button>`:''}</article>`).join('')}</div></section><section class="account-block"><div class="block-head"><div><div class="eyebrow">COMMERCIAL</div><h2>${t('offers')} · ${t('orders')}</h2></div></div><div class="account-card-grid">${[...(c.offers||[]).map(o=>`<article class="account-card"><span class="status-pill">${status(o.status)}</span><h3>${esc(l(state.catalog.lots.find(x=>x.id===o.lotId)?.title)||o.lotId)}</h3><strong>${money(o.buyerAmount||o.sellerAmount,o.currency)}</strong></article>`),...(c.orders||[]).map(orderCard)].join('')||`<div class="empty-state">${t('noActivity')}</div>`}</div></section>`}
function orderCard(o){const lot=state.catalog.lots.find(x=>x.id===o.lotId);return`<article class="account-card order-card"><div class="account-card-head"><span class="status-pill">${status(o.status)}</span><strong>${money(o.price,o.currency)}</strong></div><h3>${esc(l(lot?.title)||o.id)}</h3>${orderTimeline(o)}<button class="quiet-button" data-order="${esc(o.id)}">${t('details')}</button></article>`}
async function trustView(){if(!state.me.account?.roles?.some(r=>['CATALOGUER','TRUST_REVIEWER','ADMIN'].includes(r)))return`<section class="page section"><h1>${t('accessRestricted')}</h1></section>`;const q=await api('/api/operator/queue');return`<section class="page section"><div class="section-head"><div><div class="eyebrow">OPERATIONS</div><h1>${t('trust')}</h1><p class="muted">${state.lang==='ru'?'Каталожное одобрение, trust clearance и KYB остаются независимыми воротами публикации.':'Catalogue approval, trust clearance and KYB remain independent publication gates.'}</p></div></div><div class="trust-layout"><div>${q.drafts.map(d=>`<article class="review-card"><div class="review-head"><div><div class="micro">${esc(d.saleRoute)} · ${status(d.status)}</div><h3>${esc(l(d.title))}</h3></div><strong>${d.checklist.percent}%</strong></div><div>${d.riskFlags.map(r=>`<span class="risk ${r.severity==='BLOCK'?'block':'review'}">${esc(r.code)}</span>`).join('')}</div><div class="review-actions"><button class="quiet-button" data-op="request-changes" data-id="${esc(d.id)}">${t('requestChanges')}</button><button class="secondary-button" data-op="approve" data-id="${esc(d.id)}">${t('approve')}</button><button class="secondary-button" data-op="trust" data-id="${esc(d.id)}">${t('trustClearance')}</button><button class="primary-button" data-op="publish" data-id="${esc(d.id)}">${t('publish')}</button></div></article>`).join('')}</div><aside><h2>${t('verification')}</h2>${q.verifications.map(v=>`<div class="review-card"><strong>${esc(v.caseType)}</strong><p>${esc(v.accountId)}</p><small>${status(v.status)}</small></div>`).join('')}</aside></div></section>`}
async function collectionPage(id){const d=await api(`/api/collections/${encodeURIComponent(id)}`),c=d.collection;return`<section class="page section collection-detail"><a href="#collections" class="text-link">← ${t('collections')}</a><div class="collection-hero"><div><div class="eyebrow">${status(c.collectionType)} · ${status(c.visibility)}</div><h1>${esc(l(c.title))}</h1><p class="lead">${esc(l(c.summary))}</p><p>${esc(l(c.story))}</p></div><div class="collection-count"><strong>${c.items.length}</strong><span>${t('objects')}</span></div></div><div class="collection-timeline">${c.items.map((i,n)=>`<article class="collection-object"><button class="image-button" data-passport="${esc(i.object.id)}"><img src="${esc(i.object.image)}" alt=""></button><div><div class="micro">${String(n+1).padStart(2,'0')} · ${esc(i.section||'')}</div><h2>${esc(l(i.object.title))}</h2><p>${esc(l(i.object.maker))} · ${esc(l(i.object.period))}</p><div class="privacy-line">${t('owner')}: ${esc(l(i.object.owner)||t('privateCollection'))} · ${t('location')}: ${esc(l(i.object.location)||t('hidden'))}</div><button class="quiet-button" data-passport="${esc(i.object.id)}">${t('passport')}</button></div></article>`).join('')}</div></section>`}
function ensembleMap(e){const slots=e.slots||[];return`<section class="ensemble-map"><div class="block-head"><div><div class="eyebrow">${t('virtualReunification')}</div><h2>${t('collectionGraph')}</h2></div></div><div class="ensemble-map-stage"><div class="ensemble-map-core"><strong>${e.completeness.known}/${e.completeness.total}</strong><span>${t('known')}</span></div>${slots.map((s,i)=>{const angle=(Math.PI*2*i/Math.max(1,slots.length))-Math.PI/2,x=50+Math.cos(angle)*39,y=50+Math.sin(angle)*39;return`<button class="map-node ${String(s.status).toLowerCase().replaceAll('_','-')}" style="--x:${x}%;--y:${y}%" ${s.object?`data-passport="${esc(s.object.id)}"`:''}><b>${String(s.sortOrder).padStart(2,'0')} · ${status(s.status)}</b><span>${esc(l(s.label))}</span></button>`}).join('')}</div></section>`}
async function ensemblePage(id){const d=await api(`/api/ensembles/${encodeURIComponent(id)}`),e=d.ensemble;return`<section class="page section"><a href="#collections" class="text-link">← ${t('collections')}</a><div class="ensemble-detail-head"><div><div class="eyebrow">${t('virtualReunification')}</div><h1>${esc(l(e.title))}</h1><p class="lead">${esc(l(e.summary))}</p></div><div class="completion-panel"><div class="ensemble-orbit large"><strong>${e.completeness.knownPercent}%</strong><span>${t('known')}</span></div></div></div>${ensembleMap(e)}<div class="slot-grid">${e.slots.map(s=>`<article class="slot-card ${String(s.status).toLowerCase().replaceAll('_','-')}">${s.object?`<button class="image-button" data-passport="${esc(s.object.id)}"><img src="${esc(s.object.image)}" alt=""></button>`:'<div class="missing-object">?</div>'}<div class="micro">${status(s.status)}</div><h3>${esc(l(s.label))}</h3>${s.object?`<p>${esc(l(s.object.title))}</p>`:`<p>${t('missing')}</p>${state.me.account?`<button class="secondary-button" data-claim="${esc(s.id)}" data-ensemble="${esc(e.id)}">${t('claim')}</button>`:''}`}</article>`).join('')}</div></section>`}
async function exhibitionPage(id){const d=await api(`/api/exhibitions/${encodeURIComponent(id)}`),e=d.exhibition;return`<section class="exhibition-page"><div class="page exhibition-hero"><a href="#exhibitions" class="text-link">← ${t('exhibitions')}</a><div class="eyebrow">${t('onlineExhibition')} · ${status(e.status)}</div><h1>${esc(l(e.title))}</h1><p class="exhibition-subtitle">${esc(l(e.subtitle))}</p><div class="curatorial-statement">${esc(l(e.curatorialStatement))}</div></div>${e.sections.map((s,si)=>`<section class="exhibition-section ${si%2?'tone-paper':'tone-ink'}"><div class="page"><div class="exhibition-section-copy"><div class="eyebrow">${String(si+1).padStart(2,'0')}</div><h2>${esc(l(s.title))}</h2><p>${esc(l(s.narrative))}</p></div><div class="exhibition-items">${s.items.map(i=>i.object?`<article class="exhibition-object"><button class="image-button" data-passport="${esc(i.object.id)}"><img src="${esc(i.object.image)}" alt=""></button><div><h3>${esc(l(i.object.title))}</h3><p>${esc(l(i.caption))}</p></div></article>`:i.ensemble?`<article class="exhibition-ensemble"><div class="ensemble-orbit"><strong>${i.ensemble.completeness.knownPercent}%</strong><span>${t('known')}</span></div><div><h3>${esc(l(i.ensemble.title))}</h3><p>${esc(l(i.caption))}</p><a class="text-link" href="#ensemble/${esc(i.ensemble.id)}">${t('open')} →</a></div></article>`:'').join('')}</div></div></section>`).join('')}</section>`}
async function passport(id){state.currentLot=id;const d=await api(`/api/lots/${encodeURIComponent(id)}/passport`),o=d.lot,related=state.ensembles.filter(e=>e.slots?.some(s=>s.objectId===id)),gallery=[o.image,...(o.media||[]).map(m=>m.url).filter(Boolean)].filter((x,i,a)=>x&&a.indexOf(x)===i),dlg=$('#dialog'),commercial=d.commercial||{};const listing=commercial.listing,auction=commercial.auction,commerce=listing?`<aside class="dossier-commerce-dock"><div class="dock-summary"><span>${t('price')}</span><strong>${money(listing.price,listing.currency)}</strong><small>${methodLabel(listing.saleType)}</small></div><div class="dock-actions">${state.me.account?.roles?.includes('BUYER')?(listing.saleType==='MAKE_OFFER'?`<button class="primary-button" data-offer="${esc(listing.id)}" data-price="${listing.price}" data-currency="${listing.currency}">${t('offer')}</button>`:`<button class="primary-button" data-buy="${esc(listing.id)}">${t('buy')}</button>`):''}</div></aside>`:auction?`<aside class="dossier-commerce-dock"><div class="dock-summary"><span>${t('currentBid')}</span><strong>${money(auction.currentBid,auction.currency)}</strong><small>${auction.bidCount} ${t('bids')}</small></div><div class="dock-actions">${state.me.account?.roles?.includes('BUYER')?`<button class="primary-button" data-bid="${esc(auction.id)}" data-min="${auction.currentBid+auction.increment}">${t('bid')}</button>`:''}</div></aside>`:'';const timeline=(o.provenanceTimeline||[]).map(x=>`<li><span>${esc(x.date||'')}</span><div><strong>${esc(l(x.event))}</strong><small>${status(x.evidenceStatus)}</small></div></li>`).join('');const prov=Array.isArray(o.provenance?.[state.lang])?o.provenance[state.lang].map(x=>`<p>${esc(x)}</p>`).join(''):`<p>${esc(l(o.provenance))}</p>`;$('#dialogBody').innerHTML=`<div class="dialog-pad dossier native-dossier"><button class="dialog-close" data-close-dialog>×</button><button class="dossier-neighbor prev" data-neighbor="-1" aria-label="${t('previous')}">‹</button><button class="dossier-neighbor next" data-neighbor="1" aria-label="${t('next')}">›</button><div class="dossier-gallery"><button class="dossier-hero" data-media-index="0"><img src="${esc(gallery[0])}" alt="${esc(l(o.title))}"></button><div class="dossier-thumbs">${gallery.map((src,i)=>`<button data-thumb="${i}" class="${i===0?'active':''}"><img src="${esc(src)}" alt=""></button>`).join('')}</div></div><div class="dossier-body"><div class="dossier-toolbar"><div><div class="eyebrow">${esc(o.objectId)} · ${status(o.catalogueStatus)}</div><h2>${esc(l(o.title))}</h2><p class="lead">${esc(l(o.maker))} · ${esc(l(o.period))} · ${esc(l(o.origin))}</p></div><div class="dossier-tools"><button class="quiet-button ${isSaved(o.id)?'active':''}" data-save="${esc(o.id)}">♡ ${t('save')}</button><button class="quiet-button ${isCompared(o.id)?'active':''}" data-compare="${esc(o.id)}">⇄ ${t('compare')}</button><button class="quiet-button" data-collect="${esc(o.id)}">＋ ${t('addCollection')}</button></div></div>${commerce}<nav class="dossier-tabs"><a href="#dossier-overview">${t('researchDossier')}</a><a href="#dossier-provenance">${t('provenance')}</a><a href="#dossier-condition">${t('conditionReport')}</a><a href="#dossier-evidence">${t('evidence')}</a></nav><section id="dossier-overview"><div class="dossier-facts"><div><span>${t('materials')}</span><strong>${esc(l(o.materials))}</strong></div><div><span>${t('techniqueLabel')}</span><strong>${esc(l(o.technique))}</strong></div><div><span>${t('dimensions')}</span><strong>${esc(l(o.dimensions))}</strong></div><div><span>${t('conditionGrade')}</span><strong>${esc(l(o.conditionLabel))}</strong></div><div><span>${t('location')}</span><strong>${esc(l(o.locationLabel))}</strong></div><div><span>${t('export')}</span><strong>${status(o.exportStatus)}</strong></div></div><h3>${t('cataloguing')}</h3><p>${esc(l(o.cataloguing))}</p><h3>${t('marks')}</h3><p>${esc(l(o.marks))}</p></section><section id="dossier-provenance"><h3>${t('objectHistory')}</h3><ol class="provenance-timeline">${timeline}</ol><h3>${t('provenance')}</h3>${prov}</section><section id="dossier-condition"><h3>${t('conditionReport')}</h3><p>${esc(l(o.condition))}</p><p><strong>${t('restoration')}:</strong> ${esc(l(o.restoration))}</p></section><section id="dossier-evidence"><h3>${t('evidence')}</h3><div class="evidence-row">${(o.documents||[]).map(x=>`<span>${esc(l(x.label))} · ${status(x.status)}</span>`).join('')||'—'}</div><h3>${t('relations')}</h3>${related.length?related.map(e=>`<a class="relation-card" href="#ensemble/${esc(e.id)}" data-close-before-nav><strong>${esc(l(e.title))}</strong><span>${e.completeness?.knownPercent||0}% ${t('known')}</span></a>`).join(''):`<p class="muted">—</p>`}<h3>${t('interoperability')}</h3><div class="interoperability"><a href="/api/lots/${encodeURIComponent(o.id)}/iiif/manifest" target="_blank">IIIF Manifest</a><a href="/api/lots/${encodeURIComponent(o.id)}/linked-art" target="_blank">Linked Art JSON-LD</a></div></section><small class="dossier-disclaimer">${esc(l(d.disclaimer)||t('catalogueDisclaimer'))}</small></div></div>`;dlg.dataset.gallery=JSON.stringify(gallery);dlg.open?null:dlg.showModal();installSheetDrag(dlg)}
function nextPassport(delta){const xs=filteredEntries().map(x=>x.lot.id),all=xs.includes(state.currentLot)?xs:state.catalog.lots.map(x=>x.id),i=Math.max(0,all.indexOf(state.currentLot)),next=all[(i+delta+all.length)%all.length];if(next)passport(next).catch(e=>toast(e.message))}
function ensureMediaViewer(){if($('#mediaViewer'))return;const d=document.createElement('dialog');d.id='mediaViewer';d.className='media-viewer';d.innerHTML='<button class="media-viewer-close" data-close-media>×</button><button class="media-viewer-nav prev" data-media-nav="-1">‹</button><div class="media-stage"><img alt=""></div><button class="media-viewer-nav next" data-media-nav="1">›</button><div class="media-viewer-meta"></div>';document.body.appendChild(d);installMediaGestures(d)}
const mediaState={items:[],index:0,scale:1,x:0,y:0,pointers:new Map(),distance:0};
function openMedia(index=0){ensureMediaViewer();const dlg=$('#mediaViewer'),source=$('#dialog');try{mediaState.items=JSON.parse(source.dataset.gallery||'[]')}catch{mediaState.items=[]}if(!mediaState.items.length)return;mediaState.index=Math.max(0,Math.min(mediaState.items.length-1,index));mediaState.scale=1;mediaState.x=0;mediaState.y=0;renderMedia();dlg.showModal()}
function renderMedia(){const dlg=$('#mediaViewer'),img=$('.media-stage img',dlg);img.src=mediaState.items[mediaState.index]||'';img.style.transform=`translate3d(${mediaState.x}px,${mediaState.y}px,0) scale(${mediaState.scale})`;$('.media-viewer-meta',dlg).textContent=`${mediaState.index+1} / ${mediaState.items.length}`}
function mediaNav(delta){mediaState.index=(mediaState.index+delta+mediaState.items.length)%mediaState.items.length;mediaState.scale=1;mediaState.x=0;mediaState.y=0;renderMedia()}
function installMediaGestures(dlg){const stage=$('.media-stage',dlg),img=$('img',stage);const distance=()=>{const p=[...mediaState.pointers.values()];return p.length<2?0:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)};stage.addEventListener('pointerdown',e=>{mediaState.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY});stage.setPointerCapture?.(e.pointerId);if(mediaState.pointers.size===2)mediaState.distance=distance()});stage.addEventListener('pointermove',e=>{const p=mediaState.pointers.get(e.pointerId);if(!p)return;const oldX=p.x,oldY=p.y;p.x=e.clientX;p.y=e.clientY;if(mediaState.pointers.size===2){const d=distance();if(mediaState.distance){mediaState.scale=Math.max(1,Math.min(4,mediaState.scale*d/mediaState.distance));mediaState.distance=d}}else if(mediaState.scale>1){mediaState.x+=p.x-oldX;mediaState.y+=p.y-oldY}renderMedia()});const up=e=>{mediaState.pointers.delete(e.pointerId);mediaState.distance=distance()};stage.addEventListener('pointerup',up);stage.addEventListener('pointercancel',up);img.addEventListener('dblclick',()=>{mediaState.scale=mediaState.scale>1?1:2;mediaState.x=0;mediaState.y=0;renderMedia()})}
function openSheet(html){const d=$('#actionSheet');$('#actionSheetBody').innerHTML=html;if(!d.open)d.showModal();installSheetDrag(d);setTimeout(()=>$('input,button',d)?.focus({preventScroll:true}),20);return d}
function closeSheet(){const d=$('#actionSheet');if(d?.open)d.close()}
function installSheetDrag(dialog){if(!dialog||dialog.dataset.dragReady)return;dialog.dataset.dragReady='1';let g=dialog.querySelector(':scope > .sheet-grabber');if(!g){g=document.createElement('div');g.className='sheet-grabber';dialog.prepend(g)}let drag=null;g.addEventListener('pointerdown',e=>{if(innerWidth>800)return;drag={id:e.pointerId,y:e.clientY,dy:0};dialog.classList.add('is-dragging');g.setPointerCapture?.(e.pointerId)});dialog.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;drag.dy=Math.max(0,e.clientY-drag.y);dialog.style.setProperty('--sheet-y',`${drag.dy}px`)});const done=e=>{if(!drag||e.pointerId!==drag.id)return;const close=drag.dy>110;drag=null;dialog.classList.remove('is-dragging');dialog.style.setProperty('--sheet-y','0px');if(close&&dialog.open)dialog.close()};dialog.addEventListener('pointerup',done);dialog.addEventListener('pointercancel',done)}
function bidSheet(btn){const id=btn.dataset.bid,min=Number(btn.dataset.min||0);const d=openSheet(`<div class="action-sheet-body"><div class="action-sheet-head"><div><div class="micro">ONLINE AUCTION</div><h2>${t('maximumBid')}</h2><p>${state.lang==='ru'?'Система повышает ставку только настолько, насколько необходимо. Максимум остаётся скрытым.':'The system increases only as needed. Your maximum remains private.'}</p></div><button class="action-sheet-close" data-close-sheet>×</button></div><div class="action-sheet-field"><label>${t('maximumBid')}</label><input id="bidAmount" type="number" inputmode="numeric" min="${min}" value="${min}"></div><div class="action-sheet-actions"><button class="secondary-button" data-close-sheet>${t('close')}</button><button class="primary-button" id="confirmBid">${t('confirmBid')}</button></div></div>`);$('#confirmBid',d).onclick=async()=>{const amount=Math.round(Number($('#bidAmount',d).value)),b=$('#confirmBid',d);if(!Number.isFinite(amount)||amount<min)return toast(`${t('maximumBid')}: ≥ ${money(min)}`);b.disabled=true;try{if(!state.client.registeredSales?.includes(state.catalog.sale.id))await api(`/api/sales/${state.catalog.sale.id}/register`,{method:'POST',body:JSON.stringify({acceptTerms:true,termsVersion:'v13-preview'})});await api(`/api/auctions/${id}/bid`,{method:'POST',headers:{'idempotency-key':crypto.randomUUID()},body:JSON.stringify({maxAmount:amount})});closeSheet();await refresh();toast(t('bidSuccess'));render()}catch(e){b.disabled=false;toast(e.message)}}}
function offerSheet(btn){const id=btn.dataset.offer,asking=Number(btn.dataset.price),currency=btn.dataset.currency||'EUR',suggest=Math.round(asking*.9),d=openSheet(`<div class="action-sheet-body"><div class="action-sheet-head"><div><div class="micro">PRIVATE NEGOTIATION</div><h2>${t('offer')}</h2><p>${t('askingPrice')}: ${money(asking,currency)}</p></div><button class="action-sheet-close" data-close-sheet>×</button></div><div class="action-sheet-field"><label>${t('yourOffer')}</label><input id="offerAmount" type="number" inputmode="numeric" value="${suggest}" min="1" max="${Math.max(1,asking-1)}"></div><div class="quick-bids"><button data-offer-pct="85">85%</button><button data-offer-pct="90">90%</button><button data-offer-pct="95">95%</button></div><div class="action-sheet-actions"><button class="secondary-button" data-close-sheet>${t('close')}</button><button class="primary-button" id="confirmOffer">${t('sendOffer')}</button></div></div>`);$$('[data-offer-pct]',d).forEach(x=>x.onclick=()=>{$('#offerAmount',d).value=Math.round(asking*Number(x.dataset.offerPct)/100)});$('#confirmOffer',d).onclick=async()=>{const amount=Math.round(Number($('#offerAmount',d).value)),b=$('#confirmOffer',d);if(!Number.isFinite(amount)||amount<=0||amount>=asking)return toast(t('yourOffer'));b.disabled=true;try{await api(`/api/listings/${id}/offers`,{method:'POST',body:JSON.stringify({amount})});closeSheet();await refresh();toast(t('offerSuccess'));render()}catch(e){b.disabled=false;toast(e.message)}}}
function filterSheet(){const f=state.catalog.facets,F=state.filters,d=openSheet(`<div class="action-sheet-body native-filter-sheet"><div class="action-sheet-head"><div><div class="micro">CATALOGUE</div><h2>${t('filters')}</h2></div><button class="action-sheet-close" data-close-sheet>×</button></div>${[['category',t('category'),f.categories],['era',t('era'),f.eras],['country',t('country'),f.countries],['material',t('material'),f.materials],['technique',t('technique'),f.techniques],['condition',t('condition'),f.conditions],['location',t('location'),f.locations],['purchaseMethod',t('purchase'),f.purchaseMethods],['seller',t('seller'),f.sellers]].map(([k,label,list])=>`<label>${label}<select data-sheet-filter="${k}">${optionHtml(list,F[k],t('all'))}</select></label>`).join('')}<div class="price-filter"><span>${t('price')}</span><div><input data-sheet-filter="priceMin" type="number" value="${esc(F.priceMin)}" placeholder="${f.price.min}"><span>—</span><input data-sheet-filter="priceMax" type="number" value="${esc(F.priceMax)}" placeholder="${f.price.max}"></div></div><div class="action-sheet-actions"><button class="secondary-button" id="resetSheetFilters">${t('reset')}</button><button class="primary-button" id="applySheetFilters">${t('show')}</button></div></div>`);$('#resetSheetFilters',d).onclick=()=>{$$('[data-sheet-filter]',d).forEach(x=>x.value=x.dataset.sheetFilter.startsWith('price')?'':'ALL')};$('#applySheetFilters',d).onclick=()=>{$$('[data-sheet-filter]',d).forEach(x=>state.filters[x.dataset.sheetFilter]=x.value);closeSheet();render()}}
function twoFactorSheet(){api('/api/auth/2fa/setup',{method:'POST',body:'{}'}).then(setup=>{const d=openSheet(`<div class="action-sheet-body"><div class="action-sheet-head"><div><div class="micro">TOTP</div><h2>${t('setup2fa')}</h2><p>${state.lang==='ru'?'Добавьте секрет в приложение-аутентификатор, затем подтвердите 6-значный код.':'Add the secret to your authenticator app, then confirm the 6-digit code.'}</p></div><button class="action-sheet-close" data-close-sheet>×</button></div><div class="secret-box">${esc(setup.secret)}</div><div class="action-sheet-field"><label>Code<input id="twoFactorCode" inputmode="numeric" maxlength="6" value="${esc(setup.currentPreviewCode||'')}"></label></div><button class="primary-button" id="confirm2fa">${t('setup2fa')}</button></div>`);$('#confirm2fa',d).onclick=async()=>{try{await api('/api/auth/2fa/confirm',{method:'POST',body:JSON.stringify({code:$('#twoFactorCode',d).value})});closeSheet();await refresh();render()}catch(e){toast(e.message)}}}).catch(e=>toast(e.message))}
function claimSheet(btn){const d=openSheet(`<div class="action-sheet-body"><div class="action-sheet-head"><div><div class="micro">COLLECTION GRAPH</div><h2>${t('claim')}</h2></div><button class="action-sheet-close" data-close-sheet>×</button></div><div class="action-sheet-field"><label>ANTIQUA ID<input id="claimObjectId" placeholder="AQ-…"></label></div><div class="action-sheet-actions"><button class="secondary-button" data-close-sheet>${t('close')}</button><button class="primary-button" id="confirmClaim">${t('claim')}</button></div></div>`);$('#confirmClaim',d).onclick=async()=>{try{await api(`/api/ensembles/${btn.dataset.ensemble}/claims`,{method:'POST',body:JSON.stringify({slotId:btn.dataset.claim,objectId:$('#claimObjectId',d).value.trim()||null,evidence:[],displayOwner:false,displayLocation:false})});closeSheet();toast(state.lang==='ru'?'Заявка передана куратору':'Claim sent to curator')}catch(e){toast(e.message)}}}
async function orderSheet(id){const d=await api(`/api/orders/${encodeURIComponent(id)}`),o=d.order,lot=o.lot;openSheet(`<div class="action-sheet-body order-detail-sheet"><div class="action-sheet-head"><div><div class="micro">${esc(o.id)}</div><h2>${esc(l(lot?.title)||t('orders'))}</h2><p>${money(o.price,o.currency)} · ${status(o.status)}</p></div><button class="action-sheet-close" data-close-sheet>×</button></div>${orderTimeline(o)}<div class="order-detail-grid"><div><span>Payment</span><strong>${status(o.paymentStatus)}</strong></div><div><span>Shipping</span><strong>${status(o.shippingStatus)}</strong></div><div><span>Invoice</span><strong>${status(o.invoiceStatus)}</strong></div><div><span>Tax</span><strong>${status(o.taxStatus)}</strong></div></div></div>`)}
async function operatorAction(btn){const action=btn.dataset.op,id=btn.dataset.id;if(action==='request-changes'){const d=openSheet(`<div class="action-sheet-body"><div class="action-sheet-head"><h2>${t('requestChanges')}</h2><button class="action-sheet-close" data-close-sheet>×</button></div><div class="action-sheet-field"><textarea id="reviewNote" rows="5"></textarea></div><button class="primary-button" id="sendReview">${t('requestChanges')}</button></div>`);$('#sendReview',d).onclick=async()=>{try{await api(`/api/operator/drafts/${id}/request-changes`,{method:'POST',body:JSON.stringify({note:$('#reviewNote',d).value})});closeSheet();render()}catch(e){toast(e.message)}};return}const body=action==='trust'?{decision:'CLEARED',note:'Reviewed'}:{};await api(`/api/operator/drafts/${id}/${action}`,{method:'POST',body:JSON.stringify(body)});await refresh();render()}
function resetFilters(){state.filters={q:'',category:'ALL',era:'ALL',country:'ALL',material:'ALL',technique:'ALL',condition:'ALL',priceMin:'',priceMax:'',location:'ALL',purchaseMethod:'ALL',seller:'ALL',sort:'RECOMMENDED'}}
function refreshCatalogGrid(){const grid=$('#catalogGrid');if(!grid)return;const xs=filteredEntries();grid.innerHTML=xs.length?xs.map(card).join(''):`<div class="empty-state catalog-empty">${t('noResults')}</div>`;const count=$('#catalogCount');if(count)count.textContent=`${xs.length} ${t('results')}`;const chips=$('#activeFilters');if(chips)chips.innerHTML=filterChips();const trigger=$('[data-open-filters]');if(trigger)trigger.textContent=`${t('filters')}${activeFilterCount()?` · ${activeFilterCount()}`:''}`}
async function render(){syncShell();const raw=location.hash.slice(1)||'shop',[route,id]=raw.split('/');let html;if(route==='auctions')html=auctionsView();else if(route==='collections')html=collectionsView();else if(route==='exhibitions')html=exhibitionsView();else if(route==='dealers')html=dealersView();else if(route==='dealer'&&id)html=await dealerPage(id);else if(route==='account')html=accountView();else if(route==='trust')html=await trustView();else if(route==='collection'&&id)html=await collectionPage(id);else if(route==='ensemble'&&id)html=await ensemblePage(id);else if(route==='exhibition'&&id)html=await exhibitionPage(id);else if(route==='compare')html=compareView();else html=shop();$('#app').innerHTML=html;syncNavigation();enhance($('#app'))}
function enhance(root=document){$$('img',root).forEach(img=>{img.decoding='async';if(!img.closest('.dossier-hero'))img.loading='lazy'});$$('[data-direct-card]',root).forEach(x=>x.dataset.directCard='')}
function toggleCompare(id){const i=state.compare.indexOf(id);if(i>=0)state.compare.splice(i,1);else if(state.compare.length<4)state.compare.push(id);else return toast(t('maxCompare'));persistCompare();render().catch(e=>toast(e.message))}
async function toggleSave(id){await api(`/api/lots/${id}/save`,{method:'POST',body:JSON.stringify({enabled:!isSaved(id)})});await refresh();toast(t('saveSuccess'));render()}
async function buyNow(id){await api(`/api/listings/${id}/buy`,{method:'POST',body:'{}'});$('#dialog')?.close();await refresh();toast(t('orderSuccess'));location.hash='account'}
async function collect(id){await api(`/api/lots/${id}/collect`,{method:'POST',body:'{}'});await refresh();toast(t('addedCollection'))}
function installPressPhysics(){document.addEventListener('pointerdown',e=>{const b=e.target.closest('button,a.primary-button,a.secondary-button');if(b)b.classList.add('is-pressed');const c=e.target.closest('[data-direct-card]');if(c&&!e.target.closest('button,a,input,select,textarea')){c.classList.add('is-pressing');c._press={id:e.pointerId,x:e.clientX,y:e.clientY}}},{capture:true});document.addEventListener('pointermove',e=>{const c=e.target.closest?.('[data-direct-card]')||$('.is-pressing');if(!c?._press||c._press.id!==e.pointerId)return;c.style.setProperty('--press-x',`${Math.max(-7,Math.min(7,(e.clientX-c._press.x)*.15))}px`);c.style.setProperty('--press-y',`${Math.max(-7,Math.min(7,(e.clientY-c._press.y)*.12))}px`)},{capture:true});const up=e=>{$$('.is-pressed').forEach(x=>x.classList.remove('is-pressed'));$$('.is-pressing').forEach(c=>{c.classList.remove('is-pressing');c.style.setProperty('--press-x','0px');c.style.setProperty('--press-y','0px');delete c._press})};document.addEventListener('pointerup',up,{capture:true});document.addEventListener('pointercancel',up,{capture:true})}
function installDossierSwipe(){let s=null;const dlg=$('#dialog');dlg.addEventListener('pointerdown',e=>{if(innerWidth>800||e.target.closest('button,a,input,select,textarea,.dossier-commerce-dock'))return;s={id:e.pointerId,x:e.clientX,y:e.clientY}});dlg.addEventListener('pointerup',e=>{if(!s||s.id!==e.pointerId)return;const dx=e.clientX-s.x,dy=e.clientY-s.y;s=null;if(Math.abs(dx)>85&&Math.abs(dx)>Math.abs(dy)*1.5)nextPassport(dx<0?1:-1)})}
function cyclePersona(){if(!state.health.preview){location.hash='account';return}const r=state.me.account?.roles||[],next=r.includes('ADMIN')?'BUYER':r.includes('SELLER')?'OPERATOR':'SELLER';state.persona=next;localStorage.setItem('antiqua_persona',next);api('/api/auth/demo-login',{method:'POST',body:JSON.stringify({persona:next})}).then(refresh).then(()=>{location.hash=next==='OPERATOR'?'trust':'account';return render()}).catch(e=>toast(e.message))}
document.addEventListener('click',async e=>{try{const target=e.target.closest('button,a');if(!target)return;if(target.matches('[data-close-dialog]'))return $('#dialog').close();if(target.matches('[data-close-before-nav]'))return $('#dialog').close();if(target.matches('[data-close-sheet]'))return closeSheet();if(target.matches('[data-close-media]'))return $('#mediaViewer')?.close();if(target.dataset.mediaNav)return mediaNav(Number(target.dataset.mediaNav));if(target.dataset.lang){state.lang=target.dataset.lang;localStorage.setItem('antiqua_lang',state.lang);syncShell();return render()}if(target.id==='persona')return cyclePersona();if(target.dataset.passport){e.preventDefault();return passport(target.dataset.passport)}if(target.dataset.thumb!=null){const i=Number(target.dataset.thumb),dlg=$('#dialog'),gallery=JSON.parse(dlg.dataset.gallery||'[]');$('.dossier-hero img',dlg).src=gallery[i];$$('[data-thumb]',dlg).forEach(x=>x.classList.toggle('active',x===target));$('.dossier-hero',dlg).dataset.mediaIndex=String(i);return}if(target.dataset.mediaIndex!=null)return openMedia(Number(target.dataset.mediaIndex));if(target.dataset.neighbor)return nextPassport(Number(target.dataset.neighbor));if(target.dataset.compare)return toggleCompare(target.dataset.compare);if(target.matches('[data-clear-compare]')){state.compare=[];persistCompare();return render()}if(target.dataset.save)return toggleSave(target.dataset.save);if(target.dataset.collect)return collect(target.dataset.collect);if(target.dataset.buy)return buyNow(target.dataset.buy);if(target.dataset.offer)return offerSheet(target);if(target.dataset.bid)return bidSheet(target);if(target.matches('[data-open-filters]'))return filterSheet();if(target.matches('[data-reset-filters]')){resetFilters();return render()}if(target.dataset.clearFilter){state.filters[target.dataset.clearFilter]=target.dataset.clearFilter.startsWith('price')?'':'ALL';return render()}if(target.matches('[data-read-all]')){await api('/api/notifications/read-all',{method:'POST',body:'{}'});await refresh();return render()}if(target.matches('[data-setup-2fa]'))return twoFactorSheet();if(target.dataset.order)return orderSheet(target.dataset.order);if(target.dataset.submitDraft){await api(`/api/seller/drafts/${target.dataset.submitDraft}/submit`,{method:'POST',body:'{}'});await refresh();return render()}if(target.dataset.claim)return claimSheet(target);if(target.dataset.op)return operatorAction(target)}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='catalogSearch'){state.filters.q=e.target.value;refreshCatalogGrid()}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){state.filters[e.target.dataset.filter]=e.target.value;refreshCatalogGrid()}});
document.addEventListener('submit',async e=>{if(!['login','register'].includes(e.target.id))return;e.preventDefault();try{const body=Object.fromEntries(new FormData(e.target).entries());await api(e.target.id==='login'?'/api/auth/login':'/api/auth/register',{method:'POST',body:JSON.stringify(body)});await refresh();await render()}catch(err){toast(err.message)}});
window.addEventListener('hashchange',()=>render().catch(e=>toast(e.message)));
installPressPhysics();installDossierSwipe();installSheetDrag($('#actionSheet'));
(async()=>{try{await refresh();ensureMediaViewer();await render()}catch(e){console.error(e);toast(e.message)}})();
